con:configuration.scriptText:
def groovyUtils = new com.eviware.soapui.support.GroovyUtils( context )
def requestHolder = groovyUtils.getXmlHolder(messageExchange.requestContent)
def responseHolder = groovyUtils.getXmlHolder(messageExchange.responseContent)
def actualName = responseHolder.getNodeValue("//m:sISOCode[text() = 'GN']/following-sibling::m:sName")
def expectedName = "Guinea"

assert actualName == expectedName

con:configuration.path:
declare namespace soap='http://schemas.xmlsoap.org/soap/envelope/';
declare namespace m='http://www.oorsprong.org/websamples.countryinfo';

<MyResult>
{
for $i in //m:tCountryCodeAndName
where fn:starts-with($i/m:sName, "G")
return <m:sName>{data($i/m:sName)}</m:sName>
}
</MyResult>
